/* .email renders 354px wide: 18px past the card */

html {
  box-sizing: border-box;
}

*,
*::before,
*::after {
  box-sizing: inherit;
}

.card {
  width: 320px; /* the whole card, padding included */
  padding: 16px;
}

.email {
  width: 100%; /* the card's content box: 288px */
  padding: 12px 16px;
  border: 1px solid #ccc;
}
